import { CheckCircle2, CircleDashed, Repeat, Split, XCircle } from 'lucide-react'
import { isDeva, type AgentInfo } from '../api'
import { useI18n } from '../i18n'

// Shows what the LangGraph agent actually did for this run (stored trace; nothing here is generated by the UI).
export default function AgentTrace({ agent, onCite }: { agent: AgentInfo; onCite: (id: string) => void }) {
  const { t } = useI18n()
  const cov = Object.fromEntries((agent.coverage ?? []).map((c) => [c.task_id, c]))
  const origin = Object.fromEntries(agent.pool.map((p) => [p.evidence_id, p.origin]))
  const icon = (s?: string) => s === 'supported' ? <CheckCircle2 size={14} className="text-good" /> : s === 'partial' ? <CircleDashed size={14} className="text-warn" /> : <XCircle size={14} className="text-bad" />
  return (
    <div className="glass p-5">
      <div className="eyebrow mb-1 flex items-center gap-2"><Split size={14} />{t('agent_trace')}</div>
      <p className="mb-4 text-xs text-slate-500">
        {agent.tasks.length} sub-question{agent.tasks.length > 1 ? 's' : ''}{agent.analysis?.fallback ? ' (question kept whole)' : ''} · {agent.retrievals} retrievals ·
        {' '}{agent.followup_rounds} follow-up round{agent.followup_rounds === 1 ? '' : 's'} · {agent.llm_calls} model calls
        {agent.analysis?.rejected?.length ? ` · ${agent.analysis.rejected.length} sub-question(s) rejected by validation` : ''}
      </p>
      <ol className="space-y-3">
        {agent.tasks.map((t) => { const c = cov[t.task_id]
          return (
            <li key={t.task_id} className="rounded-xl border border-white/[0.07] p-3">
              <div className="flex items-center gap-2 text-xs"><span className="font-mono text-electric-300">{t.task_id}</span>{icon(c?.status)}<span className="text-slate-400">{c?.status ?? 'not assessed'}</span>
                <span className="ml-auto flex flex-wrap gap-1">{c?.supporting_ids.map((id) => <button key={id} onClick={() => onCite(id)} className="cite">{id}</button>)}</span></div>
              <p className={`mt-2 text-sm text-slate-200 ${isDeva(t.question) ? 'deva' : ''}`}>{t.question}</p>
              {c?.missing && <p className={`mt-1 text-xs text-warn ${isDeva(c.missing) ? 'deva' : ''}`}>Missing: {c.missing}</p>}
              {t.followup_queries?.map((q, i) => <p key={i} className={`mt-1 flex items-start gap-1.5 text-xs text-violet-300 ${isDeva(q) ? 'deva' : ''}`}><Repeat size={12} className="mt-1 shrink-0" />Follow-up search: {q}</p>)}
            </li>) })}
      </ol>
      <div className="mt-4 flex flex-wrap gap-1.5 text-[10px]">
        {agent.pool.map((p) => <span key={p.evidence_id} className="chip border-white/10 font-mono text-slate-400">{p.evidence_id}<span className="text-slate-600">{origin[p.evidence_id]}</span></span>)}
      </div>
    </div>
  )
}
